using Servicio.RetazoMarket.Business.DTOs.MovimientoMaterial;using Servicio.RetazoMarket.DataManagment.Models;
namespace Servicio.RetazoMarket.Business.Mappers;
public static class MovimientoMaterialBusinessMapper { public static MovimientoMaterialDataModel ToDataModel(CrearMovimientoMaterialRequest r)=>new(){id_material=r.id_material,tipo_movimiento=r.tipo_movimiento.Trim().ToUpperInvariant(),cantidad=r.cantidad,fecha_mov=DateTime.UtcNow,motivo_mov=r.motivo_mov.Trim(),metodo_pago=r.metodo_pago?.Trim()};public static MovimientoMaterialResponse ToResponse(MovimientoMaterialDataModel m,decimal? stock=null)=>new(){id_movimiento=m.id_movimiento,id_material=m.id_material,tipo_movimiento=m.tipo_movimiento,cantidad=m.cantidad,fecha_mov=m.fecha_mov,motivo_mov=m.motivo_mov,metodo_pago=m.metodo_pago,material_nombre=m.Material?.mat_nombre,unidad_medida=m.Material?.unidad_medida,stock_resultante=stock};}
